def lpHaarSignedBlockReader (n : ℕ) (S : Finset (Fin (2 ^ n)))
    (θ : Fin (2 ^ n) → Bool) : IntervalLp 𝕜 p →L[𝕜] 𝕜 :=
  (S.card : 𝕜)⁻¹ • ∑ k ∈ S, signedValue (θ k) (lpHaarDyadicCoefficient 𝕜 p n k)

